import {
  ChangeDetectionStrategy,
  Component,
  booleanAttribute,
  computed,
  forwardRef,
  input,
  signal,
} from '@angular/core';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';

export type VtTextFieldType = 'email' | 'password' | 'search' | 'tel' | 'text' | 'url';

@Component({
  selector: 'vt-text-field',
  standalone: true,
  template: `
    <div class="vt-text-field" [class.vt-text-field--invalid]="error()">
      @if (label()) {
        <label class="vt-text-field__label" [for]="controlId()">
          {{ label() }}
        </label>
      }

      <input
        class="vt-text-field__control"
        [attr.aria-describedby]="describedBy()"
        [attr.aria-invalid]="error() ? 'true' : null"
        [attr.autocomplete]="autocomplete()"
        [attr.placeholder]="placeholder()"
        [disabled]="isDisabled()"
        [id]="controlId()"
        [name]="name() || controlId()"
        [required]="required()"
        [type]="type()"
        [value]="value()"
        (blur)="handleTouched()"
        (input)="handleInput($event)"
      />

      @if (hint() || error()) {
        <p class="vt-text-field__message" [id]="messageId()">
          {{ error() || hint() }}
        </p>
      }
    </div>
  `,
  styleUrl: './text-field.component.scss',
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => VtTextFieldComponent),
      multi: true,
    },
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class VtTextFieldComponent implements ControlValueAccessor {
  private static nextId = 0;

  readonly autocomplete = input<string | null>(null);
  readonly controlId = input(`vt-text-field-${VtTextFieldComponent.nextId++}`);
  readonly disabled = input(false, { transform: booleanAttribute });
  readonly error = input<string | null>(null);
  readonly hint = input<string | null>(null);
  readonly label = input<string | null>(null);
  readonly name = input<string | null>(null);
  readonly placeholder = input<string | null>(null);
  readonly required = input(false, { transform: booleanAttribute });
  readonly type = input<VtTextFieldType>('text');

  protected readonly formDisabled = signal(false);
  protected readonly isDisabled = computed(() => this.disabled() || this.formDisabled());
  protected readonly messageId = computed(() => `${this.controlId()}-message`);
  protected readonly describedBy = computed(() => (this.hint() || this.error() ? this.messageId() : null));
  protected readonly value = signal('');

  private onChange: (value: string) => void = () => undefined;
  private onTouched: () => void = () => undefined;

  writeValue(value: string | null): void {
    this.value.set(value ?? '');
  }

  registerOnChange(onChange: (value: string) => void): void {
    this.onChange = onChange;
  }

  registerOnTouched(onTouched: () => void): void {
    this.onTouched = onTouched;
  }

  setDisabledState(isDisabled: boolean): void {
    this.formDisabled.set(isDisabled);
  }

  protected handleInput(event: Event): void {
    const nextValue = (event.target as HTMLInputElement).value;

    this.value.set(nextValue);
    this.onChange(nextValue);
  }

  protected handleTouched(): void {
    this.onTouched();
  }
}
