import { ChangeDetectionStrategy, Component, booleanAttribute, input } from '@angular/core';

export type VtButtonType = 'button' | 'submit' | 'reset';
export type VtButtonVariant = 'primary' | 'secondary' | 'ghost';

@Component({
  selector: 'vt-button',
  standalone: true,
  template: `
    <button
      class="vt-button"
      [class.vt-button--ghost]="variant() === 'ghost'"
      [class.vt-button--primary]="variant() === 'primary'"
      [class.vt-button--secondary]="variant() === 'secondary'"
      [disabled]="disabled()"
      [type]="type()"
    >
      <ng-content />
    </button>
  `,
  styleUrl: './button.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class VtButtonComponent {
  readonly disabled = input(false, { transform: booleanAttribute });
  readonly type = input<VtButtonType>('button');
  readonly variant = input<VtButtonVariant>('primary');
}
